using System;
using System.Collections.Generic;
using System.ComponentModel;
using System.Drawing;
using System.Data;
using System.Text;
using System.Linq;
using System.Threading.Tasks;
using System.Windows.Forms;
using DevExpress.XtraEditors;

namespace Jamera.Accounts.Account_Groups
{
    public partial class Groups : DevExpress.XtraEditors.XtraUserControl
    {
        public Groups()
        {
            InitializeComponent();
            // This line of code is generated by Data Source Configuration Wizard
            // Fill a SqlDataSource
            sqlDataSource1.Fill();
        }

        private void create_new_btn_Click(object sender, EventArgs e)
        {
            search_inp.Focus();
            New_Group new_group = new New_Group();
            new_group.Show(this);
        }

        private void list_MouseDoubleClick(object sender, MouseEventArgs e)
        {
            
        }

        private void Groups_List_Load(object sender, EventArgs e)
        {
            search_inp.Focus();
        }
        public void Refresh_Grid_Data()
        {
            this.Enabled = false;
            sqlDataSource1.RebuildResultSchema();
            sqlDataSource1.Fill();
            list.Update();
            this.Enabled = true;
            search_inp.Focus();
        }
        private void refresh_btn_Click(object sender, EventArgs e)
        {
            search_inp.Text = null;
            Refresh_Grid_Data();
        }

        private void search_inp_EditValueChanged(object sender, EventArgs e)
        {
            gridView1.ApplyFindFilter(search_inp.Text);
        }

        private void gridView1_DoubleClick(object sender, EventArgs e)
        {
            if (gridView1.DataRowCount > 0)
            {
                if (gridView1.GetFocusedRowCellValue("Code") != DBNull.Value)
                {
                    Account_Groups_Controller account_groups_controller = new Account_Groups_Controller();

                    int group_id = Convert.ToInt32(gridView1.GetFocusedRowCellValue("Code"));
                    if (account_groups_controller.Is_Group_Editable(group_id) == true)
                    {
                        Group group = new Group();
                        group.Group_Id = group_id;
                        group.Grou_Name = Convert.ToString(gridView1.GetFocusedRowCellValue("Group Name"));
                        group.Nature_Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue("Nature Id"));
                        group.Nature_Name = Convert.ToString(gridView1.GetFocusedRowCellValue("Nature"));
                        group.Group_Type = Convert.ToString(gridView1.GetFocusedRowCellValue("Group Type"));
                        Edit_Group edit_group = new Edit_Group(group);
                        edit_group.Show();
                    }
                    else
                    {
                        XtraMessageBox.Show("This is system created account group. The account group can not be modified !", "Access Denied");
                    }
                }
                
            }
        }

        public void Controls_List(object sender, KeyEventArgs e)
        {
            if (e.KeyCode == Keys.F1 || e.KeyCode == Keys.Down && search_inp.ContainsFocus)
            {
                gridView1.Focus();
            }
            if ((e.KeyCode == Keys.F2 || e.KeyCode == Keys.Enter) && list.ContainsFocus == true)
            {
                if (gridView1.DataRowCount > 0)
                {
                    if (gridView1.GetFocusedRowCellValue("Code") != DBNull.Value)
                    {
                        Account_Groups_Controller account_groups_controller = new Account_Groups_Controller();

                        int group_id = Convert.ToInt32(gridView1.GetFocusedRowCellValue("Code"));
                        if (account_groups_controller.Is_Group_Editable(group_id) == true)
                        {
                            Group group = new Group();
                            group.Group_Id = group_id;
                            group.Grou_Name = Convert.ToString(gridView1.GetFocusedRowCellValue("Group Name"));
                            group.Nature_Id = Convert.ToInt32(gridView1.GetFocusedRowCellValue("Nature Id"));
                            group.Nature_Name = Convert.ToString(gridView1.GetFocusedRowCellValue("Nature"));
                            group.Group_Type = Convert.ToString(gridView1.GetFocusedRowCellValue("Group Type"));
                            Edit_Group edit_group = new Edit_Group(group);
                            edit_group.Show();
                        }
                        else
                        {
                            XtraMessageBox.Show("This is system created account group. The account group can not be modified !", "Access Denied");
                        }
                    }

                }
            }
            if (e.KeyCode == Keys.F3 || (e.Control && e.KeyCode == Keys.F))
            {
                search_inp.Focus();
            }
            else if (e.KeyCode == Keys.F6 || (e.Control && e.KeyCode == Keys.N))
            {
                search_inp.Focus();
                New_Group new_group = new New_Group();
                new_group.Show(this);
            }
            else if (e.KeyCode == Keys.F5 || (e.Control && e.KeyCode == Keys.R))
            {
                search_inp.Text = null;
                Refresh_Grid_Data();
            }
        }

        private void search_inp_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }

        private void list_KeyDown(object sender, KeyEventArgs e)
        {
            Controls_List(sender, e);
        }
    }
}
